## PoA Manager Contract Structure

The PoA Manager contract is designed to be a thin wrapper around the Validator Manager:

```solidity
contract PoAManager is Ownable {
    IValidatorManager public immutable validatorManager;

    constructor(address _owner, address _validatorManager) {
        _transferOwnership(_owner);
        validatorManager = IValidatorManager(_validatorManager);
    }

    // Simplified validator operations
    function addValidator(...) external onlyOwner { ... }
    function removeValidator(...) external onlyOwner { ... }
    function changeValidatorWeight(...) external onlyOwner { ... }
}
```

**Is PoA Manager Required?**

No! You can absolutely transfer Validator Manager ownership directly to a multi-sig. The PoA Manager just makes the multi-sig experience smoother. For simple setups or if you're comfortable building complex transactions, direct ownership works fine.

## What the PoA Manager Does

The PoA Manager is initialized with two key addresses:

1. **Owner**: Your Safe/Ash multi-sig wallet address
2. **Validator Manager**: if your Validator Manager is behind a proxy (the default here), its **proxy** address (e.g. `0xfacade...`) — **not** the implementation you deployed earlier. (Deployed without a proxy? Use the Validator Manager address directly.)

```solidity
constructor(address _owner, address _validatorManager) {
    _transferOwnership(_owner);
    validatorManager = IValidatorManager(_validatorManager);
}
```

If your Validator Manager is behind a proxy, pass the **proxy** address (e.g. `0xfacade...`) as `_validatorManager`, never the implementation. The PoA Manager stores this address and forwards every validator call to it; pointed at the stateless implementation, those calls revert with `OwnableUnauthorizedAccount` once the multi-sig tries to use them (a Safe surfaces this as `GS013`). See [Proxy vs. Implementation](/academy/avalanche-l1/permissioned-l1s/06-multisig-setup/01-poa-manager). The Console tool below resolves the proxy automatically; this bites manual/scripted deployments.

## What Happens During Transfer

When you call `transferOwnership()`:

1. **Verification**: The Validator Manager verifies you're the current owner
2. **State Update**: The `_owner` state variable is updated to the PoA Manager address
3. **Event Emission**: An `OwnershipTransferred` event is emitted
4. **Immediate Effect**: From this moment, only the PoA Manager can call owner-restricted functions

```solidity
// Simplified transfer logic
function transferOwnership(address newOwner) public onlyOwner {
    require(newOwner != address(0), "New owner is zero address");
    _transferOwnership(newOwner);
}

function _transferOwnership(address newOwner) internal {
    address oldOwner = _owner;
    _owner = newOwner;
    emit OwnershipTransferred(oldOwner, newOwner);
}
```

## The _reward() Function

The core reward minting happens through the `_reward()` internal function in `NativeTokenStakingManager`:

```solidity
function _reward(address account, uint256 amount) internal override {
    nativeMinter.mintNativeCoin(account, amount);
}
```

This simple function wraps the Native Minter precompile's `mintNativeCoin(address addr, uint256 amount)` function, which performs the actual token minting at the protocol level.

### Code Example: How Inheritance Works

The abstract `StakingManager` defines a `_reward()` function that must be implemented by child contracts:

```solidity
// In StakingManager (abstract contract)
function _reward(address account, uint256 amount) internal virtual;
```

The `NativeTokenStakingManager` implements this function to mint native tokens:

```solidity
// In NativeTokenStakingManager (concrete implementation)
function _reward(address account, uint256 amount) internal virtual override {
    NATIVE_MINTER.mintNativeCoin(account, amount);
}
```

This is why we must deploy `NativeTokenStakingManager` rather than `StakingManager`—the abstract contract leaves `_reward()` undefined, while the concrete implementation provides the actual logic for distributing rewards via the Native Minter precompile.

```solidity
contract TokenSwap {
    address public alice;
    address public bob;
    uint256 public avaxAmount;
    uint256 public usdcAmount;
    bool public aliceDeposited;
    bool public bobDeposited;
    uint256 public deadline;

    IERC20 public usdcToken;

    // Alice creates the swap offer
    constructor(address _bob, uint256 _usdcAmount, address _usdcToken) payable {
        alice = msg.sender;
        bob = _bob;
        avaxAmount = msg.value;  // Alice deposits AVAX
        usdcAmount = _usdcAmount;
        usdcToken = IERC20(_usdcToken);
        aliceDeposited = true;
        deadline = block.timestamp + 1 hours;  // 1 hour to complete
    }

    // Bob deposits his USDC to complete the swap
    function depositUSDC() public {
        require(msg.sender == bob, "Only Bob can deposit");
        require(block.timestamp < deadline, "Swap expired");

        usdcToken.transferFrom(bob, address(this), usdcAmount);
        bobDeposited = true;

        // Automatically execute the swap
        executeSwap();
    }

    // Execute the swap once both have deposited
    function executeSwap() private {
        require(aliceDeposited && bobDeposited, "Both must deposit");

        // Send AVAX to Bob
        payable(bob).transfer(avaxAmount);

        // Send USDC to Alice
        usdcToken.transfer(alice, usdcAmount);
    }

    // If Bob doesn't deposit before deadline, Alice gets her AVAX back
    function refund() public {
        require(block.timestamp >= deadline, "Deadline not reached");
        require(!bobDeposited, "Swap already completed");

        payable(alice).transfer(avaxAmount);
    }
}
```

