### State Management

```go
// Use versioned database for atomic commits
func (vm *VM) Accept(ctx context.Context, blk *Block) error {
    batch := vm.db.NewBatch()
    defer batch.Reset()

    // Apply state changes
    for _, tx := range blk.Txs {
        if err := vm.state.Apply(batch, tx); err != nil {
            return err
        }
    }

    // Commit atomically
    return batch.Write()
}
```

