func GetEventFromLogs[T any](
    logs []*types.Log,
    parser func(*types.Log) (T, error),
) (T, error) {

    for _, log := range logs {
        event, err := parser(log)
        if err == nil {
            return event, nil
        }
    }

    var zero T
    return zero, errors.New("event not found in logs")
}

