        Eventually(func() bool {
            client := ethclient.NewClient(nodeURI + "/ext/bc/" + blockchainID.String() + "/rpc")

            block, err := client.BlockByNumber(ctx, big.NewInt(int64(blockHeight)))
            if err != nil {
